function newJourneyState(){return {confirmed:false,directionId:'',exploreStep:0,answers:{started:'',formats:[],time:''},feedback:{},existingMode:false,showSuggestions:false,feedbackDraft:{},feedbackRecords:[],trialRound:0};}
function journeyState(){if(!state.journey)state.journey=newJourneyState();return state.journey;}
function journeyDirection(){return journeyDirections.find(d=>d.id===journeyState().directionId)||journeyDirections[0];}
function journeyTopics(){return journeyDirection().topics.map(t=>({...t}));}
function journeySampleDescriptor(itemIndex){const i=Number.isInteger(itemIndex)&&itemIndex>=0&&itemIndex<3?itemIndex:0;return {topicIndex:i,experimentGoal:journeyDirection().goals[i],question:journeyTopics()[i].title};}
function journeyGuard(action){if(state.editing){toast('有未保存改稿。请先回内容页保存或撤回，再进行此操作；旧任务不会被清除。');return false;}action();return true;}
function journeyGo(route){journeyGuard(()=>go(route));}
function journeyExisting(){journeyGuard(()=>{journeyState().existingMode=true;go('automation');});}
function journeyRecommendation(){const a=journeyState().answers;const formats=a.formats||[];if(a.time==='30'&&formats.includes('review')&&a.started==='started')return {id:'notice',why:'你已开始做内容，愿意做资料审核，并选择约 30 分钟；先用公告片段练习事实与解释的边界。',limit:'这是简单规则，不代表你已具备财务审核能力；公告核验可能远超 30 分钟。'};return {id:'explain',why:a.time==='10'?'你希望先用约 10 分钟尝试，先选小切口的概念解释，少做跟踪承诺。':formats.includes('camera')?'你愿意出镜也可以先从现象解释起步：先把脚本讲清，再决定是否出镜。':'信息还不多，先从一个不需出镜、可小规模验证的财经现象解释开始。',limit:'只是待验证假设，不是精准画像；需要来源复核，也不保证粉丝、收益或能在所选时间内完成。'};}
function journeyNote(text){const n=node('div','journey-note',text);n.setAttribute('role','status');return n;}
function journeyBlock(title,text){return append(node('div','journey-block'),node('h3','',title),node('p','',text));}
function renderJourneyHome(){const j=journeyState();heading('START SMALL · 先试一小步',j.confirmed?'方向有了，先验证一篇。':'还不知道做什么？从这里开始。','股票内容创作探索 · 不必先懂运营，不必先连接模型。');const hero=node('section','journey-hero');append(hero,chip('离线交互原型 · 不是真实 AI','green'),node('h2','',j.confirmed?journeyDirection().name:'先找到一个你愿意尝试的小方向'),node('p','',j.confirmed?'不锁定长期赛道。用一轮小试做，感受资料审核和表达是否适合自己。':'回答最多 3 个生活化问题，也可以全部跳过。先看预置建议和样稿，再决定下一步。'),actions(button(j.confirmed?'查看我的小规模试做 →':'我还不知道做什么 / 帮我探索方向 →',()=>journeyGo(j.confirmed?'plan':'explore'),'button primary'),button('我已有账号或方向',journeyExisting)),node('p','journey-caption','不需要 Key · 不连接平台 · 不自动发布 · 全部内容为预置演示'));main.append(hero);if(j.confirmed){renderDirectionCard(main);const next=panel('试做之后，再决定');append(next,node('p','','发没发布都可以复盘。不要求阅读量、粉丝或收入数据。'),actions(button('记录 / 回看试做反馈',()=>journeyGo('feedback')),button('可选：了解模型接入',()=>journeyGo('providers'),'text-button')));main.append(next);}else{const steps=node('div','journey-mini-grid');[['01 / 探索','从现实时间和愿意做的事出发'],['02 / 试一篇','先看预置离线样稿，不用模型'],['03 / 再调整','记录卡点，不以数据考核自己']].forEach(([t,s])=>steps.append(journeyBlock(t,s)));main.append(steps);}journeyHistory(main);}
function journeyHistory(parent){const p=panel('本会话任务与版本');append(p,node('p','muted','不同方向的任务都会保留在这里；切换方向不会清空旧稿。重置原型或刷新页面后不保留。'));if(!state.history.length)p.append(node('p','','还没有任务。探索方向后，先看一篇演示样稿即可。'));state.history.slice().reverse().forEach(h=>{const row=node('div','journey-history');append(row,append(node('div'),node('h3','',h.title),node('p','journey-caption',h.id)),chip(h.status||'待审核'),button('查看此版本',()=>journeyGuard(()=>{state.task=JSON.parse(JSON.stringify(h.task));go('content');})));p.append(row);});parent.append(p);}
const journeyQuestions=[
 {key:'started',title:'你现在开始做股票内容了吗？',sub:'没有经验也没关系。这里不考运营知识。',options:[['new','还没开始，先了解一下'],['started','已经发过一些内容'],['unsure','不确定 / 跳过']]},
 {key:'formats',title:'哪些事，你比较愿意试一试？',sub:'可多选，也可以一个都不选。出镜不是必需项。',options:[['review','找资料、核对后做图文'],['experience','分享自己的学习经历'],['camera','对着镜头讲一讲'],['unsure','不确定 / 跳过']]},
 {key:'time',title:'一次大概愿意留多少时间？',sub:'只是安排试做节奏，不是完成时长承诺。审核可能比写作更花时间。',options:[['10','大约 10 分钟，先轻量试试'],['30','大约 30 分钟，愿意多看一点'],['unsure','时间不定 / 不确定 / 跳过']]}
];
function renderExplore(){const j=journeyState();heading('FIND YOUR FIRST ANGLE','不用先想清楚账号定位。','先回答现实情况，再看三个可尝试的股票内容方向。答案仅在本会话使用。');const shortcut=node('div','journey-shortcut');append(shortcut,node('p','','不想回答也完全可以，建议只是一个起点。'),button('都不确定，直接看看建议 →',()=>{j.answers={started:'unsure',formats:[],time:'unsure'};j.showSuggestions=true;render();},'button primary'));main.append(shortcut);if(j.showSuggestions){journeySuggestions();return;}const step=Math.max(0,Math.min(2,j.exploreStep));const q=journeyQuestions[step];const p=panel();p.classList.add('journey-question');const progress=node('div','journey-progress');progress.setAttribute('aria-label','探索进度：第 '+(step+1)+' 题，共 3 题');for(let i=0;i<3;i++)progress.append(node('span','journey-progress-segment'+(i<=step?' journey-on':'')));append(p,progress,node('div','journey-caption','问题 '+(step+1)+' / 3 · 每题都能跳过'),node('h2','',q.title),node('p','muted',q.sub));const choices=node('div','journey-choices');q.options.forEach(([value,label])=>{const val=j.answers[q.key];const selected=Array.isArray(val)?(value==='unsure'?val.length===0:val.includes(value)):val===value;const b=button(label,()=>{if(q.key==='formats'){const values=j.answers.formats||[];j.answers.formats=value==='unsure'?[]:values.includes(value)?values.filter(v=>v!==value):[...values,value];}else j.answers[q.key]=value;render();},'journey-choice'+(selected?' journey-selected':''));b.setAttribute('aria-pressed',String(selected));choices.append(b);});p.append(choices);const nav=actions();if(step>0)nav.append(button('← 上一步',()=>{j.exploreStep--;render();}));nav.append(button('跳过这题',()=>{j.answers[q.key]=q.key==='formats'?[]:'unsure';journeyNextQuestion();}),button(step===2?'看看建议 →':'下一步 →',journeyNextQuestion,'button primary'));append(p,nav,node('p','journey-caption','没有标准答案；离开再回来，会保留本会话已选答案。'));main.append(p);}
function journeyNextQuestion(){const j=journeyState();if(j.exploreStep>=2)j.showSuggestions=true;else j.exploreStep++;render();}
function journeySuggestions(){const rec=journeyRecommendation();const d=journeyDirections.find(x=>x.id===rec.id);const p=panel();p.classList.add('journey-recommend');append(p,chip('建议先试 · 待验证假设','green'),node('h2','',d.name),node('p','',rec.why),journeyNote(rec.limit),actions(button('先按主推方案试做 →',()=>journeyConfirm(d.id),'button primary'),button('返回修改回答',()=>{journeyState().showSuggestions=false;render();})));main.append(p);append(main,node('h2','journey-section-title','也可以换一个方向'),node('p','journey-caption','不必读完全部卡片才能开始。三个方向都不提供荐股、收益预测或涨粉承诺。'));const grid=node('div','journey-direction-grid');journeyDirections.forEach(dir=>{const card=node('section','journey-direction');append(card,chip(dir.id===rec.id?'规则主推':'备选方向',dir.id===rec.id?'green':''),node('h3','',dir.name),node('p','journey-caption',dir.tag),node('p','',dir.value));const details=node('details','journey-details');append(details,node('summary','','看看实际做什么、选题和风险'),journeyBlock('每次实际做什么',dir.work),journeyBlock('材料 / 能力门槛',dir.threshold));const list=node('ol','journey-topic-list');dir.topics.forEach(t=>list.append(node('li','',t.title)));append(details,node('h4','','3 篇可试选题'),list,journeyBlock('主要风险',dir.risk),journeyBlock('可能的商业化路径 · 非收益承诺',dir.money));append(card,details,button('先试「'+dir.name+'」',()=>journeyConfirm(dir.id),'button'+(dir.id===rec.id?' primary':'')));grid.append(card);});main.append(grid);main.append(journeyNote('透明规则：仅当“已开始 + 愿意资料审核 + 约 30 分钟”同时满足时主推公告阅读练习；其他情况先推低门槛解释。行业小观察因跟踪成本较高不自动主推。经历分享 / 出镜不会被当作金融专业能力。建议为预置示意，不是模型推断。'));}
function journeyConfirm(id){if(state.generating){toast('样稿正在展开，请等演示完成后再确认或更换方向，避免不同方案串台。');return;}journeyGuard(()=>{const j=journeyState();const dir=journeyDirections.find(d=>d.id===id);if(!dir)return;const apply=()=>{const changed=j.directionId!==id;if(changed){j.feedback={};j.feedbackDraft={};j.feedbackRecords=[];j.trialRound++;}j.directionId=id;j.confirmed=true;Object.assign(state.profile,dir.profile);go('plan');toast('已生成账号方向与试做建议，仅保留在本会话；没有创建真实计划。');};if(j.confirmed&&j.directionId!==id)confirmBox('换一个方向试试？','这不是锁定长期赛道。确认后将生成新方向卡，重新开始这一轮试做反馈；旧任务与版本历史完整保留。不会自动生成内容、发布或创建真实计划。',apply,'确认换方向');else if(j.confirmed){go('plan');}else apply();});}
function renderDirectionCard(parent){const j=journeyState();const p=panel('我的账号方向卡 · 系统生成');p.classList.add('journey-account');if(!j.confirmed){append(p,node('p','','还没选方向。先看建议，再由系统填好初始偏好，不用先填专业表单。'),actions(button('帮我探索方向',()=>journeyGo('explore'),'button primary'),button('我已有账号或方向',journeyExisting)));parent.append(p);return;}append(p,chip('当前试做方向 · '+journeyDirection().name,'green'),node('h3','',state.profile.brand));[['给谁看',state.profile.reader],['提供什么价值',state.profile.goal],['怎样表达',state.profile.style],['观察范围',state.profile.watch]].forEach(([label,value])=>{const row=node('div','journey-account-row');append(row,node('strong','',label),node('span','',value));p.append(row);});append(p,node('p','journey-caption','这是一张可调整的起点卡，不是长期赛道承诺。真实内容仍须核实来源并人工审核。'),actions(button('微调方向卡',journeyAdjust),button('重新探索 / 选方向',()=>journeyGo('explore')),button('高级配置',journeyExisting,'text-button')));parent.append(p);}
function journeyAdjust(){journeyGuard(()=>modal('微调方向卡 · 可留空不改',(d,close)=>{const brand=input(state.profile.brand),style=textarea(state.profile.style);append(d,node('p','muted','不用重新做定位。这里只调整名称和表达偏好，不改变方向、试做或历史。'),field('账号名称',brand),field('我希望怎么表达',style),actions(button('取消',close),button('保存微调',()=>{if(brand.value.trim())state.profile.brand=brand.value.trim().slice(0,80);if(style.value.trim())state.profile.style=style.value.trim().slice(0,500);close();render();toast('方向卡已在本会话更新。');},'button primary')));}));}
function journeyTrialCount(){const t=journeyState().answers.time;return t==='30'?3:t==='10'?2:1;}
function journeyTrialHistory(index){const j=journeyState();return state.history.filter(h=>h.task&&h.task.trialItem===index&&h.task.trialDirection===j.directionId&&(h.task.trialRound===undefined||h.task.trialRound===j.trialRound));}
function renderTrialPlan(){const j=journeyState();heading('A SMALL EXPERIMENT','先试一轮，不急着日更。','未来 7 天只建议试 1–3 篇；时间、是否发布都由你决定。此处不创建真实计划。',j.confirmed?button('直接看第一篇演示样稿 →',()=>journeyGuard(()=>startTrialContent(0,'preview')),'button primary'):null);if(!j.confirmed){append(main,journeyNote('先选一个待验证方向，就能看到试做内容。'),button('去看看方向建议',()=>journeyGo('explore'),'button primary'));return;}renderDirectionCard(main);const count=journeyTrialCount();const intro=panel('这一轮：'+count+' 篇小试做');append(intro,node('p','',j.answers.time==='10'?'按低频 2 篇安排，而不是每日更新。资料查证与审核可能超过 10 分钟，不能保证 10 分钟完成。':j.answers.time==='30'?'最多 3 篇，不用一口气做完。约 30 分钟只是意愿，资料查证与审核可能超时。':'时间不定，默认先看 1 篇样稿。什么时候做、是否发布，由你自行决定。'),journeyNote('先看演示样稿 = 读取预置离线内容，不是免费真实 AI。模拟已连接模型也不发请求；真实产品的接入是后续可选步骤。'));main.append(intro);journeyTopics().slice(0,count).forEach((topic,i)=>{const p=panel();p.classList.add('journey-trial');const history=journeyTrialHistory(i);append(p,chip('试做 '+(i+1)+' / '+count),chip(history.length?'已有 '+history.length+' 个任务版本':'尚未试做',history.length?'green':''),node('h2','',topic.title),node('p','',topic.argument),journeyBlock('这篇在验证什么',journeyDirection().goals[i]),node('p','journey-caption','建议动作：看样稿 → 核对表述与来源 → 自定是否发布 → 留一句反馈。'));append(p,actions(button(history.length?'再看演示样稿':'先看演示样稿',()=>journeyGuard(()=>startTrialContent(i,'preview')),'button primary'),button('模拟使用已连接模型',()=>journeyGuard(()=>startTrialContent(i,'connected')))));if(history.length)p.append(button('查看最近任务版本',()=>journeyGuard(()=>{state.task=JSON.parse(JSON.stringify(history[history.length-1].task));go('content');}),'text-button'));main.append(p);});const end=panel('不发布，也能得到一次有效试做');append(end,node('p','','先确认自己读不读得懂、愿不愿意核查、有没有卡住。反馈不要求平台数据，也不会自动替你换方向。'),actions(button('记录 / 回看反馈 →',()=>journeyGo('feedback'),'button primary'),button('可选：了解模型接入',()=>journeyGo('providers'))));main.append(end);}
function journeyFeedbackSuggestion(f){if(f.difficulty==='hard'||f.published==='no')return {title:'先降低一点负担',text:'可以先停留在 1 篇，缩短为一个概念解释，解决读不懂或核查卡点。未发布也值得复盘；若仍不适合，再主动选择换方向。'};if(f.difficulty==='easy')return {title:'愿意的话，再继续一篇',text:'读起来顺是一个小信号，不代表内容已核验或方向已成功。可以按自己的时间继续一篇，并保持来源核查。'};return {title:'暂时不知道，也没关系',text:'先回看一篇样稿，找一句想讲清楚的话。可以继续一篇、降低频率，或重新探索；不用现在做长期承诺。'};}
function renderTrialFeedback(){const j=journeyState();heading('NOTICE WHAT FELT HARD','先说说感受，不考核数据。','仅自报、本会话保留；未连接平台，不读取阅读量、粉丝或真实发布状态。');if(!j.confirmed){append(main,journeyNote('先选方向，再随时回来记录感受。'),button('探索一个方向',()=>journeyGo('explore'),'button primary'));return;}const f=j.feedbackDraft;const p=panel('这一轮，你的感受');[['published','这篇发了吗？',[['yes','我已自行发布'],['no','还没发布 / 卡住了'],['unknown','不知道 / 跳过']]],['difficulty','读起来、准备起来难不难？',[['easy','大体能懂，愿意再试'],['hard','有点难，想减轻负担'],['unknown','还不知道 / 跳过']]]].forEach(([key,label,options])=>{const group=node('div','journey-feedback-group');group.setAttribute('role','group');group.setAttribute('aria-label',label);group.append(node('h3','',label));const opts=node('div','journey-feedback-options');options.forEach(([value,text])=>{const b=button(text,()=>{f[key]=value;render();},'journey-choice'+(f[key]===value?' journey-selected':''));b.setAttribute('aria-pressed',String(f[key]===value));opts.append(b);});append(p,append(group,opts));});const note=textarea(f.question||'');note.rows=3;note.maxLength=500;note.placeholder='例如：还不懂订单和收入怎么区分；没发布，因为不知道去哪里核对。也可以留空。';note.addEventListener('input',()=>{f.question=note.value;});append(p,field('收到过什么问题，或自己卡在哪里？（可跳过）',note,'不要求阅读量、粉丝或收益数字。不要填写个人信息。'),actions(button('保存这次感受',()=>journeySaveFeedback(false),'button primary'),button('都不知道，跳过并看建议',()=>journeySaveFeedback(true))));main.append(p);if(j.feedback.saved){const s=journeyFeedbackSuggestion(j.feedback);const result=panel(s.title);result.classList.add('journey-recommend');append(result,node('p','',s.text),node('p','journey-caption','以下操作由你选择，不会自动切方向、自动减频或创建计划。'),actions(button('继续看看试做',()=>journeyGo('plan'),'button primary'),button('先降到 1 篇',()=>journeyGuard(()=>{j.answers.time='unsure';go('plan');toast('本轮建议改为 1 篇；原任务仍保留，没有修改真实计划。');})),button('想换个方向看看',()=>journeyGo('explore'))));main.append(result);}if(j.feedbackRecords.length){const records=panel('本轮反馈记录 · 仅自报');j.feedbackRecords.slice().reverse().forEach((record,i)=>{const row=node('div','journey-feedback-record');append(row,node('h3','','记录 '+(j.feedbackRecords.length-i)+(record.skipped?' · 已跳过':'')),node('p','','发布：'+({yes:'自报已发布',no:'还没发布 / 有卡点',unknown:'不知道'}[record.published]||'未填写')+'；难度：'+({easy:'大体能懂',hard:'有点难',unknown:'不知道'}[record.difficulty]||'未填写')),node('p','',record.question||'没有补充问题。'));records.append(row);});main.append(records);}}
function journeySaveFeedback(skip){const j=journeyState();const f=skip?{published:'unknown',difficulty:'unknown',question:'',skipped:true}:{published:j.feedbackDraft.published||'unknown',difficulty:j.feedbackDraft.difficulty||'unknown',question:(j.feedbackDraft.question||'').trim(),skipped:false};j.feedback={...f,saved:true};j.feedbackRecords.push({...j.feedback});render();toast('反馈仅保存于本会话；未读取任何平台数据。');}
